function CountOpenBrackets(brackets: string): int
    assures CountOpenBrackets(brackets) >= 0
{
    var count := 0;
    // Count the number of '<' characters in the string
    foreach i in 0 .. brackets.Length - 1 {
        if brackets[i] == '<' {
            count := count + 1;
        }
    }
    return count;
}

function CountCloseBrackets(brackets: string): int
    assures CountCloseBrackets(brackets) >= 0
{
    var count := 0;
    // Count the number of '>' characters in the string
    foreach i in 0 .. brackets.Length - 1 {
        if brackets[i] == '>' {
            count := count + 1;
        }
    }
    return count;
}

function NoUnmatchedClosingBrackets(brackets: string): bool
    ensures NoUnmatchedClosingBrackets(brackets) == (forall i :: 0 <= i < brackets.Length ==> (CountOpenBrackets(brackets[0..i]) >= CountCloseBrackets(brackets[0..i])))
{
    var openCount := 0;
    // Ensure at no point do we have more closing than opening brackets
    foreach i in 0 .. brackets.Length - 1 {
        if brackets[i] == '<' {
            openCount := openCount + 1;
        } else if brackets[i] == '>' {
            openCount := openCount - 1;
        }
        if openCount < 0 {
            return false;
        }
    }
    return true;
}
